    "ur": "ضروری دستاویزات ابھی منسلک کریں — پاسپورٹ/آئی ڈی، برتھ سرٹیفکیٹ اور ایک تصویر داخلے کے لیے درکار ہے۔ درخواست گزار کے ریکارڈ سے اختیاری دستاویزات بعد میں شامل کی جا سکتی ہیں۔",
    "hi": "अब आवश्यक दस्तावेज़ संलग्न करें - प्रवेश के लिए पासपोर्ट/आईडी, जन्म प्रमाण पत्र और एक फोटो आवश्यक है। आवेदक के रिकॉर्ड से वैकल्पिक दस्तावेज़ बाद में जोड़े जा सकते हैं।"
