  "Admissions manages applications from enquiry to enrolment. The Enrolment CRM tracks leads through New → Contacted → Toured → Application → Won, with follow-ups and conversion.": {
    "ar": "تدير وحدة القبول الطلبات من الاستفسار حتى الالتحاق، بينما يتابع نظام متابعة القبول المراحل: جديد ← تم التواصل ← جولة ← طلب ← مقبول، مع المتابعات والتحويل.",
    "ur": "داخلہ انکوائری سے اندراج تک درخواستوں کا انتظام کرتا ہے۔ انرولمنٹ CRM نئے → رابطہ شدہ → ٹورڈ → ایپلیکیشن → جیت گیا، فالو اپ اور تبدیلی کے ساتھ لیڈز کو ٹریک کرتا ہے۔",
    "hi": "प्रवेश पूछताछ से लेकर नामांकन तक आवेदनों का प्रबंधन करता है। नामांकन सीआरएम ट्रैक फॉलो-अप और रूपांतरण के साथ नए → संपर्क → दौरा → आवेदन → जीता के माध्यम से आगे बढ़ता है।"
  },
