    "ur": "عملہ کا انتظام ملازمین کے ریکارڈ، پیشہ ورانہ معاہدوں، آن بورڈنگ دستاویزات، اور چھٹیوں سے باخبر رہنے کا احاطہ کرتا ہے۔",
