  "Term 2 Fee Reminder": {
    "ar": "تذكير برسوم الفصل الدراسي ٢",
    "ur": "ٹرم 2 فیس کی یاد دہانی",
    "hi": "अवधि 2 शुल्क अनुस्मारक"
  },
  "PTC for Grades 6–12 is scheduled for Saturday, 21 June. Booking opens in the Parent portal on Tuesday.": {
    "ar": "تقرر عقد اجتماع أولياء الأمور للصفوف ٦-١٢ يوم السبت ٢١ يونيو. يفتح الحجز في بوابة ولي الأمر يوم الثلاثاء.",
    "ur": "گریڈ 6-12 کے لیے PTC ہفتہ، 21 جون کو شیڈول ہے۔ پیرنٹ پورٹل میں منگل کو بکنگ کھلتی ہے۔",
    "hi": "ग्रेड 6-12 के लिए पीटीसी शनिवार, 21 जून को निर्धारित है। मंगलवार को पेरेंट पोर्टल पर बुकिंग शुरू हो गई।"
  },
  "Project submissions for the Science Exhibition close on 18 June. Mentors, please verify your team rosters.": {
    "ar": "يُغلق باب تسليم مشاريع المعرض العلمي في ١٨ يونيو. يرجى من المشرفين التحقق من قوائم الفرق.",
    "ur": "سائنس نمائش کے لیے پروجیکٹ کی گذارشات 18 جون کو بند ہوں گی۔ سرپرست، براہ کرم اپنی ٹیم کے فہرستوں کی تصدیق کریں۔",
    "hi": "विज्ञान प्रदर्शनी के लिए परियोजना प्रस्तुतियाँ 18 जून को समाप्त होंगी। आकाओं, कृपया अपनी टीम का रोस्टर सत्यापित करें।"
  },
  "Due to road works on Al Wasl Road, Route 7 pickup moves 10 minutes earlier from Monday.": {
    "ar": "نظرًا لأعمال الطرق في شارع الوصل، سيتم تقديم موعد استلام طلاب المسار ٧ بمقدار ١٠ دقائق اعتبارًا من يوم الإثنين.",
    "ur": "الوصل روڈ پر سڑک کے کاموں کی وجہ سے، روٹ 7 کا پک اپ پیر سے 10 منٹ پہلے چلتا ہے۔",
    "hi": "अल वस्ल रोड पर सड़क कार्य के कारण, रूट 7 पिकअप सोमवार से 10 मिनट पहले चलती है।"
  },
  "Emirati author Maitha Al Khayat joins us on 24 June for a reading and Q&A with Grades 4–7.": {
    "ar": "تستضيف المدرسة الكاتبة الإماراتية ميثاء الخياط في ٢٤ يونيو لجلسة قراءة وحوار مع طلبة الصفوف ٤-٧.",
    "ur": "اماراتی مصنف میتھا الخیاط 24 جون کو گریڈ 4-7 کے ساتھ پڑھنے اور سوال و جواب کے لیے ہمارے ساتھ شامل ہیں۔",
    "hi": "अमीराती लेखिका मैथा अल खयात 24 जून को ग्रेड 4-7 के साथ पढ़ने और प्रश्नोत्तरी के लिए हमसे जुड़ती हैं।"
  },
  "Term 2 invoices are due on 20 June. Pay via the Parent portal to avoid a late-payment charge.": {
    "ar": "تستحق فواتير الفصل الدراسي ٢ في ٢٠ يونيو. يرجى السداد عبر بوابة ولي الأمر لتجنب غرامة التأخير.",
    "ur": "ٹرم 2 رسیدیں 20 جون کو واجب الادا ہیں۔ تاخیر سے ادائیگی کے چارج سے بچنے کے لیے پیرنٹ پورٹل کے ذریعے ادائیگی کریں۔",
    "hi": "टर्म 2 के चालान 20 जून को देय हैं। विलंबित भुगतान शुल्क से बचने के लिए पेरेंट पोर्टल के माध्यम से भुगतान करें।"
  },
