function schoolLocale(){return LANG==='ar'?'ar-AE':LANG==='ur'?'ur-PK':LANG==='hi'?'hi-IN':'en-GB'}
function schoolArabicDigits(s){
  if(LANG==='ar') return String(s).replace(/\d/g,n=>'٠١٢٣٤٥٦٧٨٩'[Number(n)]);
  if(LANG==='ur') return String(s).replace(/\d/g,n=>'۰۱۲۳۴۵۶۷۸۹'[Number(n)]);
  if(LANG==='hi') return String(s).replace(/\d/g,n=>'०१२३४५६७८९'[Number(n)]);
  return String(s);
}

function schoolTranslateText(value){
  const raw=String(value??''),s=raw.trim();
  if(LANG==='en'||!s)return t(s);
  if(I18N[s]&&I18N[s][LANG])return I18N[s][LANG];
  const lower=s.toLowerCase();
  if(I18N[lower]&&I18N[lower][LANG])return I18N[lower][LANG];

  let m;
  if(m=s.match(/^(\d+) accessible records$/i))return schoolArabicDigits(m[1])+' '+({ar:'سجلات متاحة',ur:'دستیاب ریکارڈ',hi:'उपलब्ध रिकॉर्ड'})[LANG];
  if(m=s.match(/^(\d+)[–-](\d+) of (\d+)$/))return schoolArabicDigits(m[1]+'–'+m[2])+' '+({ar:'من',ur:'از',hi:'का'})[LANG]+' '+schoolArabicDigits(m[3]);
  if(m=s.match(/^(\d+) calendar days$/i))return schoolArabicDigits(m[1])+' '+({ar:'يومًا تقويميًا',ur:'تقویمی دن',hi:'कैलेंडर दिन'})[LANG];
  if(m=s.match(/^(.+) Teacher$/))return ({ar:'معلم',ur:'استاد',hi:'शिक्षक'})[LANG]+' '+schoolTranslateText(m[1]);
  // Welcome, [Name]
  if(m=s.match(/^Welcome,\s*(.+?)(?:\s*👋)?$/i)){
    const wel=({ar:'مرحباً',ur:'خوش آمدید',hi:'स्वागत है'})[LANG]||'Welcome';
    const sep=(LANG==='hi'?', ':'، ');
    const name=m[1];
    return wel+sep+name+' 👋';
  }

  // Operational view · [School] · [Date]. Figures below use available server records.
  if(m=s.match(/^Operational view\s*[·-]\s*(.+?)\s*[·-]\s*(\d{4}-\d{2}-\d{2})\.\s*Figures below use available server records\.?$/i)){
    const school=m[1];
    const dt=schoolArabicDigits(m[2]);
    if(LANG==='ar')return 'نظرة تشغيلية · '+school+' · '+dt+'. الأرقام أدناه تستند إلى السجلات المتاحة على الخادم.';
    if(LANG==='ur')return 'آپریشنل منظر · '+school+' · '+dt+'۔ ذیل کے اعداد و شمار دستیاب سرور ریکارڈز سے استعمال کیے گئے ہیں۔';
    if(LANG==='hi')return 'परिचालन दृश्य · '+school+' · '+dt+'। नीचे दिए गए आंकड़े उपलब्ध सर्वर रिकॉर्ड का उपयोग करते हैं।';
  }

  // Data: available Students, Attendance, Fees & Admissions records · school timezone: [Timezone]
  if(m=s.match(/^Data:\s*available Students,\s*Attendance,\s*Fees & Admissions records\s*[·-]\s*school timezone:\s*(.+)$/i)){
    const tz=schoolTranslateText(m[1]);
    if(LANG==='ar')return 'البيانات: سجلات الطلاب والحضور والرسوم والقبول المتاحة · المنطقة الزمنية للمدرسة: '+tz;
    if(LANG==='ur')return 'ڈیٹا: دستیاب طلبہ، حاضری، فیس اور داخلے کے ریکارڈز · اسکول کا ٹائم زون: '+tz;
    if(LANG==='hi')return 'डेटा: उपलब्ध छात्र, उपस्थिति, शुल्क और प्रवेश रिकॉर्ड · स्कूल समय क्षेत्र: '+tz;
  }

  // Today: [att summary]
  if(m=s.match(/^Today:\s*(.+)$/i)){
    const todayLbl=({ar:'اليوم',ur:'آج',hi:'आज'})[LANG]||'Today';
    const parts=m[1].split(' · ');
    const trParts=parts.map(p=>{
      let sub;
      if(sub=p.match(/^(\d+)\s+(present|late|absent|unmarked)$/i)){
        const d=schoolArabicDigits(sub[1]);
        const word=({
          present:{ar:'حاضر',ur:'حاضر',hi:'उपस्थित'},
          late:{ar:'متأخر',ur:'دیر سے',hi:'देर से'},
          absent:{ar:'غائب',ur:'غیر حاضر',hi:'अनुपस्थित'},
          unmarked:{ar:'غير مسجل',ur:'غیر نشان زد',hi:'अचिह्नित'}
        })[sub[2].toLowerCase()]?.[LANG]||sub[2];
        return d+' '+word;
      }
      return schoolTranslateText(p);
    });
    return todayLbl+': '+trParts.join(' · ');
  }

  // KPI note: "• 0% of AED 17,000 billed", "of AED 17,000 billed"
  if(m=s.match(/^([•▲▼])?\s*(\d+%(?:\s*[•▲▼])?)\s+of\s+(.+?)\s+billed$/i)){
    const bullet=m[1]||'';
    const pct=schoolArabicDigits(m[2]);
    const amt=schoolArabicDigits(m[3]);
    if(LANG==='ar')return (bullet?bullet+' ':'')+pct+' من '+amt+' مفوتر';
    if(LANG==='ur')return (bullet?bullet+' ':'')+amt+' کے بل کا '+pct;
    if(LANG==='hi')return (bullet?bullet+' ':'')+amt+' बिल का '+pct;
  }
  if(m=s.match(/^of\s+(.+?)\s+billed$/i)){
    const amt=schoolArabicDigits(m[1]);
    if(LANG==='ar')return 'من '+amt+' مفوتر';
    if(LANG==='ur')return amt+' کے بل سے';
    if(LANG==='hi')return amt+' बिल में से';
  }
  if(m=s.match(/^of\s+([A-Z]{3}\s*[\d.,]+[KkMm]?|unavailable)$/i)){
    const ofLbl=({ar:'من',ur:'از',hi:'का'})[LANG]||'of';
    if(m[1].toLowerCase()==='unavailable'){
      const un=({ar:'غير متاح',ur:'دستیاب نہیں',hi:'अनुपलब्ध'})[LANG]||'unavailable';
      return ofLbl+' '+un;
    }
    const amt=m[1].replace(/K$/i,({ar:' ألف',ur:' ہزار',hi:' हज़ार'})[LANG]||'K');
    return ofLbl+' '+schoolArabicDigits(amt);
  }
  if(m=s.match(/^Billed\s+(.+?)\s*·\s*collected is sum of payments;\s*due\/overdue are outstanding balances\.?$/i)){
    const billedAmt=schoolArabicDigits(m[1]);
    if(LANG==='ar')return 'المفوتر '+billedAmt+' · المحصل هو مجموع المدفوعات؛ المستحق/المتأخر هو الرصيد المتبقي.';
    if(LANG==='ur')return 'بل شدہ '+billedAmt+' · وصول شدہ ادائیگیاں ہیں؛ واجب الادا/بقایا بقایا جات ہیں۔';
    if(LANG==='hi')return 'बिल किया गया '+billedAmt+' · संकलित भुगतान का योग है; देय/अतिदेय बकाया शेष हैं।';
  }
  if(m=s.match(/^(\d+)\s+unmarked$/i)){
    const count=schoolArabicDigits(m[1]);
    const lbl=({ar:'غير مسجل',ur:'غیر نشان زد',hi:'अचिह्नित'})[LANG]||'unmarked';
    return count+' '+lbl;
  }
  if(m=s.match(/^(\d+)\s+marked present\/late$/i)){
    const count=schoolArabicDigits(m[1]);
    const lbl=({ar:'سُجل حاضر/متأخر',ur:'حاضر/دیر سے نشان زد',hi:'उपस्थित/देर दर्ज'})[LANG]||'marked present/late';
    return count+' '+lbl;
  }

  if(m=s.match(/^Grade (\d+)(.*)$/)){
    const lbl=({ar:'الصف',ur:'گریڈ',hi:'कक्षा'})[LANG]||'Grade';
    return lbl+' '+schoolArabicDigits(m[1])+(m[2]?' '+schoolTranslateText(m[2]):'');
  }
  if(m=s.match(/^KG (\d+)(.*)$/)){
    const lbl=({ar:'الروضة',ur:'کے جی',hi:'केजी'})[LANG]||'KG';
    return lbl+' '+schoolArabicDigits(m[1])+(m[2]?' '+schoolTranslateText(m[2]):'');
  }

  // Specific regex patterns
  if(m=s.match(/^Admissions · (.+)$/)){
    const lbl=({ar:'القبول',ur:'داخلے',hi:'प्रवेश'})[LANG]||'Admissions';
    return lbl+' · '+(schoolTranslateText(m[1])||m[1]);
  }
  if(m=s.match(/^Applicant · (.+)$/)){
    const lbl=({ar:'متقدم',ur:'امیدوار',hi:'आवेदक'})[LANG]||'Applicant';
    return lbl+' · '+schoolTranslateText(m[1]);
  }
  if(m=s.match(/^Documents · (\d+)\/(\d+)(?: · (\d+) required pending)?$/)){
    const lbl=({ar:'المستندات',ur:'دستاویزات',hi:'दस्तावेज़'})[LANG]||'Documents';
    const req=({ar:'إلزامية لم تُستكمل',ur:'لازمی زیر التواء',hi:'अनिवार्य लंबित'})[LANG]||'required pending';
    const ofLbl=({ar:'من',ur:'از',hi:'का'})[LANG]||'of';
    return lbl+' · '+schoolArabicDigits(m[1])+' '+ofLbl+' '+schoolArabicDigits(m[2])+(m[3]?' · '+schoolArabicDigits(m[3])+' '+req:'');
  }
  if(m=s.match(/^Advance to (.+)$/)){
    const lbl=({ar:'الانتقال إلى',ur:'آگے بڑھیں',hi:'आगे बढ़ें'})[LANG]||'Advance to';
    return lbl+' '+schoolTranslateText(m[1]);
  }
  if(m=s.match(/^(Mon|Tue|Wed|Thu|Fri) · today$/)){
    const day=MULTILINGUAL_DAYS[m[1]]?.[LANG]||m[1];
    const today=({ar:'اليوم',ur:'آج',hi:'आज'})[LANG]||'today';
    return day+' · '+today;
  }
  if(m=s.match(/^Page (\d+)(?: of | \/ )(\d+)(.*)$/)){
    const pLbl=({ar:'الصفحة',ur:'صفحہ',hi:'पृष्ठ'})[LANG]||'Page';
    const ofLbl=({ar:'من',ur:'از',hi:'का'})[LANG]||'of';
    return pLbl+' '+schoolArabicDigits(m[1])+' '+ofLbl+' '+schoolArabicDigits(m[2])+(m[3]?' '+schoolTranslateText(m[3]):'');
  }
  if(m=s.match(/^(\d+) of (\d+) (.+)$/)){
    const ofLbl=({ar:'من',ur:'از',hi:'का'})[LANG]||'of';
    const word=MULTILINGUAL_COUNT_WORDS[m[3]]?.[LANG]||schoolTranslateText(m[3]);
    return schoolArabicDigits(m[1])+' '+ofLbl+' '+schoolArabicDigits(m[2])+' '+word;
  }
  if(m=s.match(/^Page (\d+)$/)){
    const page=({ar:'الصفحة',ur:'صفحہ',hi:'पृष्ठ'})[LANG]||'Page';
    return page+' '+schoolArabicDigits(m[1]);
  }
  if(m=s.match(/^(\d+) (\w+)$/)){
    if(MULTILINGUAL_COUNT_WORDS[m[2]]&&MULTILINGUAL_COUNT_WORDS[m[2]][LANG]){
      if(LANG==='ar'&&m[2]==='tickets'){
        const category=new Intl.PluralRules('ar').select(Number(m[1]));
        const forms={zero:'طلبات دعم',one:'طلب دعم',two:'طلبا دعم',few:'طلبات دعم',many:'طلب دعم',other:'طلب دعم'};
        return schoolArabicDigits(m[1])+' '+forms[category];
      }
      return schoolArabicDigits(m[1])+' '+MULTILINGUAL_COUNT_WORDS[m[2]][LANG];
    }
  }

  // Date formatted: "12 Jun", "21 June 2026"
  if(m=s.match(/^(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec|January|February|March|April|June|July|August|September|October|November|December)(?:\s+(\d{4}))?$/i)){
    const mo=m[2].charAt(0).toUpperCase()+m[2].slice(1).toLowerCase();
    const moTrans=MULTILINGUAL_MONTHS[mo]?.[LANG]||MULTILINGUAL_MONTHS[m[2]]?.[LANG]||m[2];
    return schoolArabicDigits(m[1])+' '+moTrans+(m[3]?' '+schoolArabicDigits(m[3]):'');
  }

  // Search / Toggle / Enable / Open
  if(m=s.match(/^(Search|Toggle|Enable|Open)\s+(.+)$/)){
    const vMap={
      Search:{ar:'البحث في',ur:'تلاش کریں',hi:'खोजें'},
      Toggle:{ar:'تغيير تفعيل',ur:'ٹوگل کریں',hi:'टॉगल करें'},
      Enable:{ar:'تفعيل',ur:'فعال کریں',hi:'सक्षम करें'},
      Open:{ar:'فتح',ur:'کھولیں',hi:'खोलें'}
    };
    const tail=schoolTranslateText(m[2]);
    if(tail!==m[2]||(vMap[m[1]]&&vMap[m[1]][LANG]))return (vMap[m[1]]?.[LANG]||m[1])+' '+tail;
  }

  // View X
  if(m=s.match(/^View\s+(.+)$/)){
    const vLbl=({ar:'عرض',ur:'دیکھیں',hi:'देखें'})[LANG]||'View';
    return vLbl+' '+schoolTranslateText(m[1]);
  }

  // AI Insights Review Signals: "X active students cross the rule priority threshold · Y stock items below reorder level."
  if(m=s.match(/^(\d+)\s+active students cross the rule priority threshold\s*·\s*(\d+)\s+stock items below reorder level\.?$/i)){
    const d1=schoolArabicDigits(m[1]), d2=schoolArabicDigits(m[2]);
    if(LANG==='ar')return d1+' طالب نشط يتجاوزون حد أولوية القواعد · '+d2+' عناصر مخزون تحت مستوى إعادة الطلب.';
    if(LANG==='ur')return d1+' فعال طلبہ قواعد کی ترجیحی حد کو عبور کرتے ہیں · '+d2+' اسٹاک آئٹمز دوبارہ آرڈر کی سطح سے کم ہیں۔';
    if(LANG==='hi')return d1+' सक्रिय छात्र नियम प्राथमिकता सीमा पार करते हैं · '+d2+' स्टॉक वस्तुएं पुन:ऑर्डर स्तर से नीचे हैं।';
  }

  // Calculated ... · Fixed rules; school staff review source records.
  if(m=s.match(/^Calculated\s+(.+?)\s*·\s*Fixed rules;\s*school staff review source records\.?$/i)){
    const dt=m[1];
    if(LANG==='ar')return 'تم الحساب في '+dt+' · قواعد ثابتة؛ يقوم موظفو المدرسة بمراجعة السجلات المصدرية.';
    if(LANG==='ur')return 'حساب کیا گیا '+dt+' · مقررہ قواعد؛ اسکول کا عملہ بنیادی ریکارڈز کا جائزہ لیتا ہے۔';
    if(LANG==='hi')return 'गणना की गई '+dt+' · निश्चित नियम; स्कूल कर्मचारी स्रोत रिकॉर्ड की समीक्षा करते हैं।';
  }

  // Calculated ... · X active students checked · School day Y
  if(m=s.match(/^Calculated\s+(.+?)\s*·\s*(\d+)\s+active students checked\s*·\s*School day\s+(.+?)$/i)){
    const dt=m[1], count=schoolArabicDigits(m[2]), day=m[3];
    if(LANG==='ar')return 'تم الحساب في '+dt+' · تم فحص '+count+' طالب نشط · اليوم الدراسي '+day;
    if(LANG==='ur')return 'حساب کیا گیا '+dt+' · '+count+' فعال طلبہ کی جانچ کی گئی · اسکول کا دن '+day;
    if(LANG==='hi')return 'गणना की गई '+dt+' · '+count+' सक्रिय छात्रों की जाँच की गई · स्कूल दिवस '+day;
  }

  // Admissions pipeline: "X applications across the Y-stage pipeline for the Z intake. Drag a card to move stages, or click to manage documents."
  if(m=s.match(/^(\d+)\s+applications across the\s+(\d+)-stage pipeline for the\s+(.+?)\s+intake\.\s*Drag a card to move stages,\s*or click to manage documents\.?$/i)){
    const appCount=schoolArabicDigits(m[1]), stageCount=schoolArabicDigits(m[2]), intake=schoolArabicDigits(m[3]);
    if(LANG==='ar')return appCount+' طلبات عبر خط المراحل المكون من '+stageCount+' مراحل لقبول '+intake+'. اسحب بطاقة لنقل المراحل، أو انقر لإدارة المستندات.';
    if(LANG==='ur')return intake+' کے داخلے کے لیے '+stageCount+'-مرحلہ پائپ لائن میں '+appCount+' درخواستیں۔ مراحل کو تبدیل کرنے کے لیے کارڈ کھینچیں، یا دستاویزات کے انتظام کے لیے کلک کریں۔';
    if(LANG==='hi')return intake+' प्रवेश हेतु '+stageCount+'-चरणीय पाइपलाइन में '+appCount+' आवेदन। चरणों को बदलने के लिए कार्ड खींचें, या दस्तावेज़ प्रबंधित करने के लिए क्लिक करें।';
  }

  // CRM Subtitle: "Nurture prospective families from first enquiry to enrolment. X active leads · Y follow-ups due."
  if(m=s.match(/^Nurture prospective families from first enquiry to enrolment\.\s*(\d+)\s+active leads\s*·\s*(\d+)\s+follow-ups due\.?$/i)){
    const actCount=schoolArabicDigits(m[1]), dueCount=schoolArabicDigits(m[2]);
    if(LANG==='ar')return 'رعاية الأسر المرتقبة من الاستفسار الأول حتى التسجيل. '+actCount+' عملاء مهتمين نشطين · '+dueCount+' متابعات مستحقة.';
    if(LANG==='ur')return 'پہلی پوچھ گچھ سے لے کر داخلے تک متوقع خاندانوں کی رہنمائی کریں۔ '+actCount+' فعال لیڈز · '+dueCount+' فالو اپ واجب الادا ہیں۔';
    if(LANG==='hi')return 'पहली पूछताछ से लेकर नामांकन तक संभावित परिवारों का मार्गदर्शन करें। '+actCount+' सक्रिय लीड · '+dueCount+' अनुवर्ती देय।';
  }

  // KPI Trend: "enrolled 0 ▲", "won 1 ▲", "▲ 1 won", "▲ 0 enrolled", "0 enrolled", "1 won"
  if((m=s.match(/^([•▲▼])?\s*(\d+)\s+(enrolled|won|marked present\/late)\s*([•▲▼])?$/i))||
     (m=s.match(/^([•▲▼])?\s*(enrolled|won|marked present\/late)\s+(\d+)\s*([•▲▼])?$/i))){
    const arrow=m[1]||m[4]||'';
    const num=m[2]&&/^\d+$/.test(m[2])?m[2]:m[3];
    const word=(m[3]&&!/^\d+$/.test(m[3])?m[3]:m[2]).toLowerCase();
    const trWord=({
      enrolled:{ar:'تم التسجيل',ur:'داخلہ مکمل',hi:'नामांकित'},
      won:{ar:'مقبول',ur:'کامیاب',hi:'सफल'},
      'marked present/late':{ar:'سُجل حاضر/متأخر',ur:'حاضر/دیر سے نشان زد',hi:'उपस्थित/देर दर्ज'}
    })[word]?.[LANG]||word;
    const d=schoolArabicDigits(num);
    return arrow?(arrow+' '+d+' '+trWord):(d+' '+trWord);
  }

  // Uploaded docs badge: "uploaded 0/3", "uploaded 1/3", "0/3 uploaded", "3/3 complete", "complete 3/3"
  if(m=s.match(/^(?:(uploaded|complete)\s+)?(\d+)\/(\d+)(?:\s+(uploaded|complete))?$/i)){
    const status=(m[1]||m[4]||'').toLowerCase();
    const d1=schoolArabicDigits(m[2]), d2=schoolArabicDigits(m[3]);
    const trStatus=({
      uploaded:{ar:'مرفوع',ur:'اپ لوڈ شدہ',hi:'अपलोड'},
      complete:{ar:'مكتمل',ur:'مکمل',hi:'पूर्ण'}
    })[status]?.[LANG]||status;
    return (d1+'/'+d2+' '+trStatus).trim();
  }

  // Docs count in admissions cards: "0/3 docs", "3/3 docs"
  if(m=s.match(/^(\d+)\/(\d+)\s+docs$/i)){
    const d1=schoolArabicDigits(m[1]), d2=schoolArabicDigits(m[2]);
    const lbl=({ar:'مستندات',ur:'دستاویزات',hi:'दस्तावेज़'})[LANG]||'docs';
    return d1+'/'+d2+' '+lbl;
  }

  // Search matching records: "accessible records · 3 matching", "3 matching"
  if(m=s.match(/^(?:accessible records\s*·\s*)?(\d+)\s+matching(?:\s*·\s*accessible records)?$/i)){
    const d=schoolArabicDigits(m[1]);
    if(LANG==='ar')return 'سجلات يمكن الوصول إليها · '+d+' مطابقة';
    if(LANG==='ur')return 'قابل رسائی ریکارڈز · '+d+' مماثل';
    if(LANG==='hi')return 'सुलभ रिकॉर्ड · '+d+' मेल खाते';
  }
  if(m=s.match(/^(\d+)\s+matching$/i)){
    const d=schoolArabicDigits(m[1]);
    const lbl=({ar:'مطابقة',ur:'مماثل',hi:'मेल खाते'})[LANG]||'matching';
    return d+' '+lbl;
  }

  // X records/reservations/students/applications · Page Y
  if(m=s.match(/^(\d+)\s+(records|reservations|students|applications|leads|cards|visits)\s*·\s*Page\s+(\d+)$/i)){
    const d1=schoolArabicDigits(m[1]), d2=schoolArabicDigits(m[3]);
    const word=({
      records:{ar:'سجلات',ur:'ریکارڈز',hi:'रिकॉर्ड'},
      reservations:{ar:'حجوزات',ur:'ریزرویشنز',hi:'आरक्षण'},
      students:{ar:'طلاب',ur:'طلبہ',hi:'छात्र'},
      applications:{ar:'طلبات',ur:'درخواستیں',hi:'आवेदन'},
      leads:{ar:'عملاء مهتمين',ur:'لیڈز',hi:'लीड'},
      cards:{ar:'بطاقات',ur:'کارڈز',hi:'कार्ड'},
      visits:{ar:'زيارات',ur:'دورے',hi:'दौरे'}
    })[m[2].toLowerCase()]?.[LANG]||m[2];
    const pageLbl=({ar:'الصفحة',ur:'صفحہ',hi:'पृष्ठ'})[LANG]||'Page';
    return d1+' '+word+' · '+pageLbl+' '+d2;
  }

  // Idle days: "12d idle"
  if(m=s.match(/^(\d+)d idle$/i)){
    const d=schoolArabicDigits(m[1]);
    if(LANG==='ar')return d+' أيام خامل';
    if(LANG==='ur')return d+' دن غیر فعال';
    if(LANG==='hi')return d+' दिन निष्क्रिय';
  }

  // Roll number: "Roll 101"
  if(m=s.match(/^Roll\s+(\d+)$/i)){
    const d=schoolArabicDigits(m[1]);
    const lbl=({ar:'رقم القيد',ur:'رول نمبر',hi:'रोल नंबर'})[LANG]||'Roll';
    return lbl+' '+d;
  }

  // Audience tags: "to Parents", "to All", "to Students", "to Staff"
  if(m=s.match(/^to\s+(Parents|All|Students|Staff)$/i)){
    const audMap={
      parents:{ar:'إلى أولياء الأمور',ur:'والدین کے لیے',hi:'अभिभावकों के लिए'},
      all:{ar:'إلى الجميع',ur:'سب کے لیے',hi:'सभी کے لیے'},
      students:{ar:'إلى الطلاب',ur:'طلبہ کے لیے',hi:'छात्रों के लिए'},
      staff:{ar:'إلى الموظفين',ur:'اسٹاف کے لیے',hi:'कर्मचारियों کے لیے'}
    };
    return audMap[m[1].toLowerCase()]?.[LANG]||s;
  }

  // via X
  if(m=s.match(/^via\s+(.+)$/i)){
    const viaLbl=({ar:'عبر',ur:'بذریعہ',hi:'के माध्यम से'})[LANG]||'via';
    return viaLbl+' '+schoolTranslateText(m[1]);
  }

  // Splitters for compounds: " · ", " — ", " -> ", " → "
  if(s.includes(' · ')){
    const parts=s.split(' · ');
    const tr=parts.map(p=>schoolTranslateText(p.trim()));
    if(tr.some((p,i)=>p!==parts[i].trim()))return tr.join(' · ');
  }
  if(s.includes(' — ')){
    const parts=s.split(' — ');
    const tr=parts.map(p=>schoolTranslateText(p.trim()));
    if(tr.some((p,i)=>p!==parts[i].trim()))return tr.join(' — ');
  }
  if(s.includes(' → ')||s.includes(' -> ')){
    const sep=s.includes(' → ')?' → ':' -> ';
    const parts=s.split(sep);
    const tr=parts.map(p=>schoolTranslateText(p.trim()));
    if(tr.some((p,i)=>p!==parts[i].trim()))return tr.join(' → ');
  }

  return t(s);
}

function schoolApiError(message,code){
  if(LANG==='en')return message;
  const translated=schoolTranslateText(message);
  if(translated!==message)return translated;
  const errMap={
    ar:{
      VALIDATION_ERROR:'تعذر التحقق من البيانات. راجع الحقول المطلوبة والقيم والتواريخ.',
      BAD_REQUEST:'تعذر قبول الطلب. راجع البيانات والمتطلبات قبل المحاولة.',
      FORBIDDEN:'لا تملك صلاحية هذا الإجراء أو هذا السجل.',
      UNAUTHORIZED:'انتهت الجلسة أو بيانات الدخول غير صحيحة. سجّل الدخول مجددًا.',
      NOT_FOUND:'السجل المطلوب غير موجود أو غير متاح لحسابك.',
      CONFLICT:'يتعارض الطلب مع حالة السجل الحالية أو بيانات محفوظة أخرى. حدّث السجلات وراجع المتطلبات.',
      INTERNAL_ERROR:'تعذر إكمال الإجراء بسبب خطأ في الخدمة. أعد المحاولة أو تواصل مع الدعم.'
    },
    ur:{
      VALIDATION_ERROR:'ڈیٹا کی توثیق نہیں ہو سکی۔ مطلوبہ فیلڈز اور اقدار چیک کریں۔',
      BAD_REQUEST:'درخواست قبول نہیں کی جا سکی۔ ضروریات کی جانچ کریں۔',
      FORBIDDEN:'آپ کو اس عمل کی اجازت نہیں ہے۔',
      UNAUTHORIZED:'سیشن ختم ہو گیا۔ دوبارہ سائن ان کریں۔',
      NOT_FOUND:'ریکارڈ نہیں ملا۔',
      CONFLICT:'درخواست موجودہ ریکارڈ سے متصادم ہے۔',
      INTERNAL_ERROR:'سروس کی خرابی۔ دوبارہ کوشش کریں۔'
    },
    hi:{
      VALIDATION_ERROR:'डेटा सत्यापित करने में विफल। आवश्यक फ़ील्ड और मान जाँचें।',
      BAD_REQUEST:'अनुरोध स्वीकार नहीं किया जा सका। आवश्यकताएँ जाँचें।',
      FORBIDDEN:'आपको इस कार्रवाई की अनुमति नहीं है।',
      UNAUTHORIZED:'सत्र समाप्त। पुनः साइन इन करें।',
      NOT_FOUND:'रिकॉर्ड नहीं मिला।',
      CONFLICT:'अनुरोध वर्तमान रिकॉर्ड से टकराता है।',
      INTERNAL_ERROR:'सेवा त्रुटि। पुनः प्रयास करें।'
    }
  };
  return (errMap[LANG]&&errMap[LANG][code])||'Operation could not be completed.';
}

(function(){const nativeConfirm=window.confirm?window.confirm.bind(window):()=>true;window.confirm=function(message){return nativeConfirm(schoolTranslateText(message))}})();

