function schoolLocalizeShell(){
  document.querySelectorAll('#rolePill,#userRole').forEach(el=>{el.removeAttribute('data-i18n-skip');el.textContent=t(state.role)});
  document.querySelectorAll('.sb-user .n').forEach(el=>{
    el.setAttribute('data-i18n-skip','true');
    const profiles = {
      Administrator: ["Rashid Al Maktoum", "RA"],
      Principal: ["Dr. Salma Haddad", "SH"],
      Teacher: ["Rohan Mehta", "RM"],
      Accountant: ["Joseph Thomas", "JT"],
      Parent: ["Khalid Al Hashimi", "KA"],
      Student: ["Fatima Al Hashimi", "FA"]
    };
    const rawName = window.SCHOOLOS_ADAPTER?.user?.name || profiles[state.role]?.[0] || 'Rashid Al Maktoum';
    el.textContent = rawName;
  });
  document.querySelectorAll('.sb-ctx .tx .n, .sb-brand .b1, .lx-brand .lx-b1, .sb-user .n').forEach(el=>el.setAttribute('data-i18n-skip','true'));
  const it=(typeof flatItems==='function'?flatItems():[]).find(x=>x.id===state.module)||{label:'Dashboard',group:'Overview'};
  const cr=document.getElementById('crumb'),tb=document.getElementById('tbTitle');
  if(cr){cr.removeAttribute('data-i18n-skip');cr.textContent=t(it.group);}
  if(tb){tb.removeAttribute('data-i18n-skip');tb.textContent=t(it.label);}
  document.querySelectorAll('.sb-user .ua,.bot-msg.me').forEach(el=>el.setAttribute('data-i18n-skip','true'));
  document.querySelectorAll('.topbar,.sidebar,#sidebar,.sb-foot,#cmdk,#botPanel,#botFab,#landing,#drawer,#toasts').forEach(localizeView);
}

